"""Authentication and account-lifecycle operations."""

from __future__ import annotations

from .common import OperationAdder, json_body, obj, path_parameter, query_parameter, string


def add_operations(add: OperationAdder) -> None:
    """Add this operation family to the contract path catalog."""
    # Authentication and account lifecycle, ordered by path and HTTP method.
    add("/auth/account", "get", operation_id="getAccountDeletion", tag="Account lifecycle", summary="Get account deletion saga", success_schema="UserDeletionSaga")
    add("/auth/account", "delete", operation_id="deleteAccount", tag="Account lifecycle", summary="Start durable account deletion", success_schema="DeleteAccountResponse", success_status="202", success_headers=("SetCookie",), description="Starts the cross-service deletion saga and clears the refresh cookie.")
    add("/auth/account/deletion", "get", operation_id="getAccountDeletionStatus", tag="Account lifecycle", summary="Get account deletion saga status", success_schema="UserDeletionSaga")
    add("/auth/email/check", "post", operation_id="checkEmailAvailability", tag="Authentication", summary="Check email availability", request_body=json_body("EmailCheckRequest"), success_schema="EmailAvailabilityResponse", security="none")
    add("/auth/email/signup", "post", operation_id="signupWithEmail", tag="Authentication", summary="Create an email account", request_body=json_body("EmailSignupRequest"), success_schema="SignupResponse", security="none")
    add("/auth/email/verify", "post", operation_id="verifyEmail", tag="Authentication", summary="Verify an email challenge", request_body=json_body("EmailVerifyRequest"), success_schema="SignupResponse", security="none")
    add("/auth/login", "post", operation_id="login", tag="Authentication", summary="Login with email and password", request_body=json_body("LoginRequest"), success_schema="AuthResponse", security="none", success_headers=("SetCookie",), description="Returns an access token and sets the refresh token as an HttpOnly cookie. The response body never exposes the refresh token.")
    add("/auth/logout", "post", operation_id="logout", tag="Authentication", summary="Revoke the current refresh session", success_schema=None, success_status="204", success_description="Logged out and refresh cookie cleared", security="refresh", success_headers=("SetCookie",))
    provider_parameter = path_parameter("provider", "OAuth provider", schema=string(enum=["GOOGLE", "APPLE", "X", "TWITTER"]))
    add("/auth/oauth/{provider}/authorize", "get", operation_id="authorizeOAuth", tag="OAuth", summary="Begin OAuth authorization", security="none", success_schema=None, success_status="302", success_description="Redirect to provider and set one-time OAuth state cookie", success_headers=("Location", "SetCookie"), parameters=[provider_parameter])
    add("/auth/oauth/{provider}/callback", "get", operation_id="completeOAuthCallback", tag="OAuth", summary="Complete OAuth callback", security="oauth_state", success_schema="AuthResponse", success_headers=("SetCookie",), parameters=[provider_parameter, query_parameter("code", "Provider authorization code", required=True), query_parameter("state", "One-time OAuth state matching the state cookie", required=True)], description="The browser must include the provider-specific HttpOnly OAuth state cookie created by the authorize endpoint. Swagger UI sends it automatically when the operation is executed in the same browser after authorization.")
    apple_parameter = path_parameter("provider", "Only Apple supports this form POST flow; spelling is case-insensitive", schema=string(enum=["APPLE"]))
    completion_fields = {
        "code": string(minLength=1, maxLength=4096, description="Provider code, at most 4096 UTF-8 bytes; nonblank and without control characters"),
        "state": string(minLength=1, maxLength=512, description="Original state, at most 512 UTF-8 bytes; nonblank and without control characters"),
    }
    success_form = obj({**completion_fields, "id_token": string(description="Ignored; never forwarded or reflected"), "user": string(description="Ignored provider profile JSON string; never forwarded or reflected")}, required=["code", "state"], additionalProperties=False)
    error_form = obj({"state": completion_fields["state"], "error": string(), "error_description": string(), "id_token": string(), "user": string()}, required=["error", "state"], additionalProperties=False)
    def form_body(schema: dict) -> dict:
        return {"required": True, "description": "URL-encoded body limited to 32768 bytes, including streamed bodies. Duplicate fields and invalid percent encoding or UTF-8 are rejected with 400.", "content": {"application/x-www-form-urlencoded": {"schema": schema}}}
    add("/auth/oauth/{provider}/callback", "post", operation_id="receiveAppleOAuthFormPost", tag="OAuth", summary="Receive Apple cross-site form POST", security="none", request_body=form_body({"oneOf": [success_form, error_form]}), parameters=[apple_parameter], success_schema=string(), success_media_type="text/html", success_headers=("CacheControl",), success_description="No-store intermediate HTML; no Auth call, session issuance or cookie modification", description="A successful form returns a nonce-CSP HTML page that submits only code and state to the same-origin completion endpoint, with a manual Continue button if JavaScript is disabled. 200 does not mean authenticated. The original SameSite=Lax state cookie may be absent on this cross-site POST. The page neither sets nor clears cookies. Provider cancellation/error, code+error, unsupported providers, malformed/ambiguous/oversized forms and unsupported media types return a generic JSON 400 without downstream Auth calls. Optional id_token/user are ignored. All responses use no-store, no-referrer and nosniff; HTML also forbids framing and external resources. Do not log or persist code/state/form bodies or put them in URLs.")
    add("/auth/oauth/{provider}/callback/complete", "post", operation_id="completeAppleOAuthFormPost", tag="OAuth", summary="Complete Apple sign-in in the original browser", security="oauth_state", request_body=form_body(obj(completion_fields, required=["code", "state"], additionalProperties=False)), parameters=[apple_parameter], success_schema="AuthResponse", success_headers=("SetCookie", "CacheControl"), description="Submitted by the Gateway-origin intermediate page. Requires exactly one original oauth_state_apple cookie equal to the form state; missing, mismatched, other-provider or duplicate cookies return 400 before Auth. Auth atomically consumes provider/state before exchanging the code and rejects expired, consumed or racing state. Success sets the refresh HttpOnly cookie and clears the Apple state cookie; refreshToken in JSON is empty. Responses use no-store/no-referrer/nosniff. A timeout may follow state consumption or session creation: never automatically resubmit, infer rollback or generate replacement state to retry this callback. GET callbacks remain available unchanged.")
    add("/auth/oauth/{provider}/link", "post", operation_id="linkOAuthIdentity", tag="OAuth", summary="Link an OAuth identity", security="bearer_oauth_state", request_body=json_body("OAuthLinkRequest"), success_schema="LinkedProvidersResponse", success_headers=("SetCookie",), parameters=[provider_parameter], description="Requires Bearer authentication and the provider-specific HttpOnly OAuth state cookie. access_token query parameters are rejected.")
    add("/auth/password/reset/confirm", "post", operation_id="confirmPasswordReset", tag="Authentication", summary="Confirm a password reset", request_body=json_body("PasswordResetConfirmRequest"), success_schema="PasswordResetResponse", security="none")
    add("/auth/password/reset/request", "post", operation_id="requestPasswordReset", tag="Authentication", summary="Request a password reset", request_body=json_body("PasswordResetRequest"), success_schema="PasswordResetResponse", security="none", description="Returns the same public status regardless of whether the account exists.")
    add("/auth/refresh", "post", operation_id="refreshAccessToken", tag="Authentication", summary="Rotate the refresh session", success_schema="AuthResponse", security="refresh", success_headers=("SetCookie",), description="Requires the refresh_token cookie. Swagger UI cannot manually set an HttpOnly cookie; first authenticate in the same browser origin.")
    add("/shadow/auth/login", "post", operation_id="shadowLogin", tag="Parity", summary="Compare source and target login behavior", request_body=json_body("LoginRequest"), success_schema="ShadowComparisonResponse", security="none", description="Available only in parity runtime mode.")
